def make_plan(query,scope,budget,allowed_tools,*,claims=(),read_followup=False):
    query=query.strip()
    if not query or len(query)>600:raise WorkspaceConflict('evidence_query_invalid')
    cross=scope.kind=='private_project' and any(t in query.casefold() for t in ('跨文件','调用','callers','references','测试','tests'))
    exact=bool(re.search(r'`[A-Za-z_][\w.]*`|\b[A-Za-z_]\w*[_\.][A-Za-z_]\w*',query))
    kind='read_followup' if read_followup else 'runtime_evidence' if 'runtime_measurements_unverified' in risk_flags(query,claims) else 'cross_file' if cross else 'exact_symbol' if exact else 'semantic'
    content={'query':query,'scope':scope.model_dump(),'budget':budget.model_dump(),'kind':kind,'allowed_tools':allowed_tools}
    return RetrievalPlan(plan_id='plan-'+fingerprint(content),query=query,scope=scope,kind=kind,allowed_tools=list(allowed_tools),
        budget=budget,required_paths=2 if cross else 1,needs_imports=scope.kind=='private_project' and any(t in query.casefold() for t in ('import','导入')),
        needs_full_definition=scope.kind=='private_project' and any(t in query.casefold() for t in ('完整','whole definition','full definition')))

def _load(self,owner,project_id,snapshot):
    stored=self.indexes.load(owner,project_id,snapshot)
    report=self._report_view(stored['report'],snapshot,_internal=True)
    if report.get('status')!='indexed':raise WorkspaceConflict('code_index_not_ready')
    rows=stored['symbols']
    if {r['symbol_id']:sha256(r['payload'].encode()).hexdigest() for r in rows}!=report['symbol_payload_hashes']:raise WorkspaceConflict('code_symbol_integrity_failed')
    symbols=[json.loads(r['payload']) for r in rows];chunks=[]
    for row in stored['chunks']:
        if sha256(row['payload'].encode()).hexdigest()!=row['payload_hash']:raise WorkspaceConflict('code_chunk_integrity_failed')
        chunks.append(KnowledgeChunk.model_validate_json(row['payload']))
    edges=stored['edges']
    if {c.chunk_id:sha256(c.model_dump_json().encode()).hexdigest() for c in chunks}!=report['chunk_payload_hashes']:raise WorkspaceConflict('code_chunk_manifest_changed')
    if digest(sorted(edges,key=lambda e:(e['source_id'],e['target_id'],e['kind'],e['line'])))!=report['edges_hash']:raise WorkspaceConflict('code_relation_integrity_failed')
    return report,symbols,chunks,edges

